INSERT INTO trucker.date_dim_pg
  (id, date_id, d_date, month_seq, week_seq, quarter_seq, d_year, dow, moy,
   dom, qoy, fy_year, fy_quarter_seq, fy_week_seq, day_name, quarter_name,
   holiday, weekend, following_holiday, first_dom, last_dom, same_day_ly,
   same_day_lq, current_day, current_week, current_month, current_quarter,
   current_year, deleted)
SELECT r.id,
       r.date_id,
       r.d_date,
       r.month_seq::int,
       r.week_seq::int,
       r.quarter_seq::int,
       r.d_year::int,
       r.dow::int,
       r.moy::int,
       r.dom::int,
       r.qoy::int,
       r.fy_year::int,
       r.fy_quarter_seq::int,
       r.fy_week_seq::int,
       r.day_name,
       r.quarter_name,
       r.holiday,
       r.weekend,
       r.following_holiday,
       r.first_dom::int,
       r.last_dom::int,
       r.same_day_ly::int,
       r.same_day_lq::int,
       r.current_day,
       r.current_week,
       r.current_month,
       r.current_quarter,
       r.current_year,
       {{ .operation | eq "delete" }}
FROM {{ .rows }}
ON CONFLICT (id) DO UPDATE SET
  date_id           = EXCLUDED.date_id,
  d_date            = EXCLUDED.d_date,
  month_seq         = EXCLUDED.month_seq,
  week_seq          = EXCLUDED.week_seq,
  quarter_seq       = EXCLUDED.quarter_seq,
  d_year            = EXCLUDED.d_year,
  dow               = EXCLUDED.dow,
  moy               = EXCLUDED.moy,
  dom               = EXCLUDED.dom,
  qoy               = EXCLUDED.qoy,
  fy_year           = EXCLUDED.fy_year,
  fy_quarter_seq    = EXCLUDED.fy_quarter_seq,
  fy_week_seq       = EXCLUDED.fy_week_seq,
  day_name          = EXCLUDED.day_name,
  quarter_name      = EXCLUDED.quarter_name,
  holiday           = EXCLUDED.holiday,
  weekend           = EXCLUDED.weekend,
  following_holiday = EXCLUDED.following_holiday,
  first_dom         = EXCLUDED.first_dom,
  last_dom          = EXCLUDED.last_dom,
  same_day_ly       = EXCLUDED.same_day_ly,
  same_day_lq       = EXCLUDED.same_day_lq,
  current_day       = EXCLUDED.current_day,
  current_week      = EXCLUDED.current_week,
  current_month     = EXCLUDED.current_month,
  current_quarter   = EXCLUDED.current_quarter,
  current_year      = EXCLUDED.current_year,
  deleted           = EXCLUDED.deleted
